#include "WebSocket.h"
#include "Config.h"
namespace { String toJson(JsonDocument& d){String s;serializeJson(d,s);return s;} bool validInt(JsonVariantConst v,int lo,int hi,int& out){if(!v.is<int>()&&!v.is<long>())return false;out=v.as<int>();return out>=lo&&out<=hi;} bool validFloat(JsonVariantConst v,float lo,float hi,float& out){if(!v.is<float>()&&!v.is<int>()&&!v.is<long>())return false;out=v.as<float>();return isfinite(out)&&out>=lo&&out<=hi;} }
RadarWebSocket* RadarWebSocket::_instance=nullptr;
RadarWebSocket::RadarWebSocket(Radar& r,Alarm& a,Logger& l,WifiManager& w):_localWs("/ws"),_radar(r),_alarm(a),_logger(l),_wifi(w){}
void RadarWebSocket::begin(AsyncWebServer& server){_instance=this;_localWs.onEvent([this](AsyncWebSocket* s,AsyncWebSocketClient* c,AwsEventType t,void* a,uint8_t* d,size_t n){onLocalEvent(s,c,t,a,d,n);});server.addHandler(&_localWs);_cloudWs.onEvent(RadarWebSocket::cloudEventRouter);_cloudWs.setReconnectInterval(Config::CLOUD_RETRY_MS);_cloudWs.enableHeartbeat(15000,3000,2);}
void RadarWebSocket::onLocalEvent(AsyncWebSocket*,AsyncWebSocketClient* c,AwsEventType t,void* arg,uint8_t* data,size_t len){if(t==WS_EVT_CONNECT){sendConfig(c,false);broadcastStatus();return;}if(t!=WS_EVT_DATA)return;AwsFrameInfo* i=static_cast<AwsFrameInfo*>(arg);if(!i||!i->final||i->index!=0||i->len!=len||i->opcode!=WS_TEXT||len==0||len>4096){sendError("Mensagem WebSocket inválida.",c,false);return;}handleIncoming(data,len,c,false);}
void RadarWebSocket::handleIncoming(const uint8_t* data,size_t len,AsyncWebSocketClient* c,bool cloud){JsonDocument d;if(deserializeJson(d,data,len)){sendError("JSON inválido.",c,cloud);return;}String type=d["type"]|"";if(type=="command")handleCommand(d["command"]|"",c,cloud);else if(type=="settings"){JsonObjectConst o=d["settings"].as<JsonObjectConst>();if(o.isNull())sendError("Objeto settings ausente.",c,cloud);else handleSettings(o,c,cloud);}else if(type=="ping"){JsonDocument p;p["type"]="pong";p["timestamp"]=millis();sendText(toJson(p),c,cloud);}else sendError("Tipo de mensagem não suportado.",c,cloud);}
void RadarWebSocket::handleCommand(const String& cmd,AsyncWebSocketClient* c,bool cloud){if(cmd=="start")_radar.start();else if(cmd=="stop")_radar.stop();else if(cmd=="center")_radar.center();else if(cmd=="restart")_radar.restart();else if(cmd=="alarm_on"){_alarm.setDetectionEnabled(true);Config::save();}else if(cmd=="alarm_off"){_alarm.setDetectionEnabled(false);Config::save();}else if(cmd=="led_on")_alarm.setManualLed(true);else if(cmd=="led_off")_alarm.setManualLed(false);else if(cmd=="clear_logs")_logger.clear();else if(cmd=="export_logs"){exportLogs(c,cloud);return;}else if(cmd=="get_config"){sendConfig(c,cloud);return;}else if(cmd!="clear_radar"){sendError("Comando não reconhecido.",c,cloud);return;}sendAck("Comando executado.",c,cloud);broadcastStatus();}
void RadarWebSocket::handleSettings(JsonObjectConst o,AsyncWebSocketClient* c,bool cloud){int iv;float fv;int smin=Config::settings.servoMinAngle,smax=Config::settings.servoMaxAngle;if(!o["servoMinAngle"].isNull()&&!validInt(o["servoMinAngle"],0,170,smin)){sendError("Ângulo mínimo inválido.",c,cloud);return;}if(!o["servoMaxAngle"].isNull()&&!validInt(o["servoMaxAngle"],10,180,smax)){sendError("Ângulo máximo inválido.",c,cloud);return;}if(smin>=smax){sendError("Ângulo mínimo deve ser menor que o máximo.",c,cloud);return;}Config::settings.servoMinAngle=smin;Config::settings.servoMaxAngle=smax;if(!o["servoStep"].isNull()){if(!validInt(o["servoStep"],1,15,iv)){sendError("Passo inválido.",c,cloud);return;}Config::settings.servoStep=iv;}if(!o["servoMoveIntervalMs"].isNull()){if(!validInt(o["servoMoveIntervalMs"],5,100,iv)){sendError("Velocidade inválida.",c,cloud);return;}Config::settings.servoMoveIntervalMs=iv;}if(!o["maxDistanceCm"].isNull()){if(!validFloat(o["maxDistanceCm"],30,400,fv)){sendError("Distância máxima inválida.",c,cloud);return;}Config::settings.maxDistanceCm=fv;}if(!o["alarmDistanceCm"].isNull()){if(!validFloat(o["alarmDistanceCm"],5,400,fv)){sendError("Distância de alarme inválida.",c,cloud);return;}Config::settings.alarmDistanceCm=fv;}if(Config::settings.alarmDistanceCm>Config::settings.maxDistanceCm){sendError("Alarme não pode superar distância máxima.",c,cloud);return;}if(!o["buzzerEnabled"].isNull())Config::settings.buzzerEnabled=o["buzzerEnabled"].as<bool>();if(!o["ledEnabled"].isNull())Config::settings.ledEnabled=o["ledEnabled"].as<bool>();if(!o["alarmEnabled"].isNull())Config::settings.alarmEnabled=o["alarmEnabled"].as<bool>();bool wifiChanged=false,cloudChanged=false;if(!o["staSsid"].isNull()){String v=o["staSsid"].as<String>();if(v.length()>32){sendError("SSID inválido.",c,cloud);return;}wifiChanged=v!=Config::settings.staSsid;Config::settings.staSsid=v;}if(!o["staPassword"].isNull()){String v=o["staPassword"].as<String>();if(!v.isEmpty()&&(v.length()<8||v.length()>63)){sendError("Senha Wi-Fi inválida.",c,cloud);return;}if(!v.isEmpty()){wifiChanged|=v!=Config::settings.staPassword;Config::settings.staPassword=v;}}if(!o["cloudEnabled"].isNull()){bool v=o["cloudEnabled"].as<bool>();cloudChanged|=v!=Config::settings.cloudEnabled;Config::settings.cloudEnabled=v;}if(!o["cloudHost"].isNull()){String v=Config::normalizeCloudHost(o["cloudHost"].as<String>());cloudChanged|=v!=Config::settings.cloudHost;Config::settings.cloudHost=v;}if(!o["cloudDeviceId"].isNull()){String v=o["cloudDeviceId"].as<String>();if(!Config::isValidCloudIdentity(v)){sendError("Device ID inválido.",c,cloud);return;}cloudChanged|=v!=Config::settings.cloudDeviceId;Config::settings.cloudDeviceId=v;}if(!o["cloudToken"].isNull()){String v=o["cloudToken"].as<String>();if(v.length()<8||!Config::isValidCloudIdentity(v)){sendError("Token inválido.",c,cloud);return;}cloudChanged|=v!=Config::settings.cloudToken;Config::settings.cloudToken=v;}Config::sanitize();if(!Config::save()){sendError("Falha ao salvar configurações.",c,cloud);return;}_radar.applySettings();if(wifiChanged)_wifi.requestStationReconnect();if(cloudChanged)_cloudEnabledSnapshot=!Config::settings.cloudEnabled;sendAck("Configurações salvas.",c,cloud);sendConfig(c,cloud);broadcastStatus();}
void RadarWebSocket::sendText(const String& p,AsyncWebSocketClient* c,bool cloud){if(cloud){if(_cloudConnected)_cloudWs.sendTXT(p);}else if(c)c->text(p);else _localWs.textAll(p);}void RadarWebSocket::sendAck(const String& m,AsyncWebSocketClient* c,bool cloud){JsonDocument d;d["type"]="ack";d["message"]=m;sendText(toJson(d),c,cloud);}void RadarWebSocket::sendError(const String& m,AsyncWebSocketClient* c,bool cloud){JsonDocument d;d["type"]="error";d["message"]=m;sendText(toJson(d),c,cloud);}
void RadarWebSocket::sendConfig(AsyncWebSocketClient* c,bool cloud){JsonDocument d;d["type"]="config";JsonObject x=d["config"].to<JsonObject>();x["servoMinAngle"]=Config::settings.servoMinAngle;x["servoMaxAngle"]=Config::settings.servoMaxAngle;x["servoStep"]=Config::settings.servoStep;x["servoMoveIntervalMs"]=Config::settings.servoMoveIntervalMs;x["maxDistanceCm"]=Config::settings.maxDistanceCm;x["alarmDistanceCm"]=Config::settings.alarmDistanceCm;x["buzzerEnabled"]=Config::settings.buzzerEnabled;x["ledEnabled"]=Config::settings.ledEnabled;x["alarmEnabled"]=Config::settings.alarmEnabled;x["staSsid"]=Config::settings.staSsid;x["cloudEnabled"]=Config::settings.cloudEnabled;x["cloudHost"]=Config::settings.cloudHost;x["cloudDeviceId"]=Config::settings.cloudDeviceId;x["cloudToken"]=Config::settings.cloudToken;sendText(toJson(d),c,cloud);}
void RadarWebSocket::exportLogs(AsyncWebSocketClient* c,bool cloud){String id=String(millis(),HEX);JsonDocument b;b["type"]="csv_begin";b["transferId"]=id;b["entries"]=_logger.size();sendText(toJson(b),c,cloud);String chunk=_logger.csvHeader();chunk.reserve(Config::CSV_CHUNK_SIZE+128);for(size_t i=0;i<_logger.size();++i){LogEntry e;if(!_logger.getEntry(i,e))continue;String line=_logger.csvLine(e);if(chunk.length()+line.length()>=Config::CSV_CHUNK_SIZE){JsonDocument d;d["type"]="csv_chunk";d["transferId"]=id;d["data"]=chunk;sendText(toJson(d),c,cloud);chunk="";}chunk+=line;}if(!chunk.isEmpty()){JsonDocument d;d["type"]="csv_chunk";d["transferId"]=id;d["data"]=chunk;sendText(toJson(d),c,cloud);}JsonDocument e;e["type"]="csv_end";e["transferId"]=id;sendText(toJson(e),c,cloud);}
void RadarWebSocket::broadcastReading(const RadarReading& r){JsonDocument d;d["type"]="radar";d["angle"]=r.angle;d["distance"]=r.valid?r.distanceCm:-1.0f;d["valid"]=r.valid;d["alarm"]=r.alarm;d["timestamp"]=r.timestamp;d["event"]=r.event;d["rssi"]=r.rssi;String p=toJson(d);_localWs.textAll(p);if(_cloudConnected)_cloudWs.sendTXT(p);}void RadarWebSocket::broadcastStatus(){const RadarStats&s=_radar.stats();JsonDocument d;d["type"]="status";d["running"]=_radar.running();d["alarmActive"]=_alarm.active();d["alarmEnabled"]=_alarm.detectionEnabled();d["cloudConnected"]=_cloudConnected;d["wifiStationConnected"]=_wifi.stationConnected();d["apClients"]=_wifi.apClients();d["rssi"]=_wifi.rssi();d["apIp"]=_wifi.apIp();d["stationIp"]=_wifi.stationIp();d["uptime"]=millis();d["freeHeap"]=ESP.getFreeHeap();d["psram"]=ESP.getPsramSize();d["freePsram"]=ESP.getFreePsram();d["readings"]=s.readings;d["alarms"]=s.alarms;d["objectsDetected"]=s.objectsDetected;d["minDistance"]=s.minDistanceCm;d["maxDistance"]=s.maxDistanceCm;d["lastDistance"]=s.lastDistanceCm;d["angle"]=s.lastAngle;d["sensorOk"]=s.sensorOk;String p=toJson(d);_localWs.textAll(p);if(_cloudConnected)_cloudWs.sendTXT(p);}
void RadarWebSocket::startCloud(){if(!_wifi.stationConnected()||!Config::settings.cloudEnabled||Config::settings.cloudHost.isEmpty())return;_cloudHostSnapshot=Config::settings.cloudHost;_cloudDeviceSnapshot=Config::settings.cloudDeviceId;_cloudTokenSnapshot=Config::settings.cloudToken;_cloudEnabledSnapshot=Config::settings.cloudEnabled;String path="/api/ws?role=device&deviceId="+_cloudDeviceSnapshot+"&token="+_cloudTokenSnapshot;_cloudWs.beginSSL(_cloudHostSnapshot.c_str(),443,path.c_str());_cloudWs.setReconnectInterval(Config::CLOUD_RETRY_MS);_cloudWs.enableHeartbeat(15000,3000,2);_cloudInitialized=true;_lastCloudAttemptMs=millis();}void RadarWebSocket::stopCloud(){if(_cloudInitialized)_cloudWs.disconnect();_cloudInitialized=false;_cloudConnected=false;}void RadarWebSocket::syncCloud(){bool desired=Config::settings.cloudEnabled&&!Config::settings.cloudHost.isEmpty();bool changed=desired!=_cloudEnabledSnapshot||Config::settings.cloudHost!=_cloudHostSnapshot||Config::settings.cloudDeviceId!=_cloudDeviceSnapshot||Config::settings.cloudToken!=_cloudTokenSnapshot;if(!desired||!_wifi.stationConnected()){if(_cloudInitialized)stopCloud();return;}if(changed&&_cloudInitialized)stopCloud();if(!_cloudInitialized&&millis()-_lastCloudAttemptMs>=1000)startCloud();}
void RadarWebSocket::cloudEventRouter(WStype_t t,uint8_t* p,size_t n){if(_instance)_instance->onCloudEvent(t,p,n);}void RadarWebSocket::onCloudEvent(WStype_t t,uint8_t* p,size_t n){if(t==WStype_CONNECTED){_cloudConnected=true;JsonDocument h;h["type"]="device_hello";h["deviceId"]=Config::settings.cloudDeviceId;h["firmware"]="1.0.0";h["timestamp"]=millis();_cloudWs.sendTXT(toJson(h));sendConfig(nullptr,true);broadcastStatus();}else if(t==WStype_DISCONNECTED||t==WStype_ERROR)_cloudConnected=false;else if(t==WStype_TEXT&&p&&n>0&&n<=4096)handleIncoming(p,n,nullptr,true);}void RadarWebSocket::update(){_localWs.cleanupClients();syncCloud();if(_cloudInitialized)_cloudWs.loop();}
